/* ==========================================================================
   RL · IMAT — English overlay
   Sin dependencias. Módulo ES.

   Capa de traducción sobre el español, que es el idioma fuente y vive en el
   HTML y en las cadenas del JS (ver assets/i18n.js). Aquí SOLO va el inglés.

   Reglas al añadir o cambiar una entrada:

   1. Los valores son HTML. Se pueden usar <strong>, <em> y fórmulas \\(...\\)
      exactamente igual que en la página en español.
   2. Terminología: la del propio Sutton & Barto, que es la fuente del glosario
      ES↔EN de Teoria/referencia/notacion.md. No se traduce "hacia atrás" desde
      el español: se usa el término original inglés (return, backup diagram,
      action-value, on-policy, eligibility traces…).
   3. Los símbolos matemáticos NO cambian entre idiomas. Sí cambian el
      separador decimal (1,50 → 1.50) y el espacio del porcentaje (79 % → 79%),
      pero de eso se encarga num()/pct() en nucleo.js, no este fichero.
   4. Las CITAS DE DIAPOSITIVAS se sustituyen por referencias a Sutton & Barto.
      El material de clase está en español y quien lee esta versión no lo
      tiene; una cita a "1_Tema1#page-24" no le sirve de nada. La sección y la
      figura del libro sí. Verificadas contra Teoria/Experto/indice/indice.md.
   5. Si falta una clave, la página muestra el español. Es un hueco visible,
      no un error silencioso — y hay un test que lo caza (tests/i18n.test.js).
   ========================================================================== */

