  "t1.m3.lectura.mejor":
    "At the end of the horizon ({pasos} steps, averaged over {runs} problems) the strategy " +
    "that picks the optimal action most often is <strong>{nombre}</strong>, at {pct}.",
  "t1.m3.lectura.cruce":
    "<strong>The crossover happens around step {paso}:</strong> from there on ε = 0.01 " +
    "overtakes ε = 0.1. It explores ten times less, so it takes far longer to find the best " +
    "arm, but once it has found it, it exploits it 99% of the time instead of 90%. That is " +
    "the answer to the question the book’s figure leaves open.",
  "t1.m3.lectura.sinCruce":
    "With this horizon the crossover between ε = 0.1 and ε = 0.01 is not visible yet: push " +
    "the steps above 5000 and run again.",
  "t1.m3.lectura.deriva":
    "Once the environment is moving, the <strong>sample average 1/n stops working</strong>: " +
    "it gives what it saw at the start the same weight as what it has just seen, so it drags " +
    "stale information along. The constant step size α keeps a recency-weighted average and " +
    "tracks the optimum. This is also the answer to “does " +
    "\\(\\sum \\alpha_n^2 &lt; \\infty\\) hold for a constant α?”: it does not, and that is " +
    "precisely why the agent never stops learning.",

  "t1.m4.ejeY": "Average reward ({pasos} steps)",
  "t1.m4.resumen.item": "<strong>{nombre}</strong>: best at {parametro} = {valor} ({media})",
  "t1.m4.lectura":
    "Notice that <em>every</em> curve is bell-shaped: overshooting on exploration costs as " +
    "much as falling short. And that the horizontal axis mixes parameters that mean " +
    "different things — the valid comparison is the height of each curve’s maximum, not its " +
    "position.",

  "t1.m5.reg.bandit.nombre": "k-armed bandit",
  "t1.m5.reg.bandit.desc":
    "The environment has no states: each decision is independent of the previous ones, you " +
    "are always in the same situation. All the agent has to estimate is \\(q_*(a)\\), one " +
    "number per action. This is “RL without states”, and it is the whole of Unit 1.",
  "t1.m5.reg.contextual.nombre": "Contextual (associative) bandit",
  "t1.m5.reg.contextual.desc":
    "Now the environment presents different situations and the agent has to learn " +
    "\\(q_*(s,a)\\): which action is good <em>in each context</em>. But its actions " +
    "<strong>do not change</strong> which context comes next, so there are still no " +
    "long-term consequences: being greedy within each situation is enough.",
  "t1.m5.reg.mdp.nombre": "General RL environment — an MDP",
  "t1.m5.reg.mdp.desc":
    "Actions now influence future states, so a high reward now can cost larger rewards " +
    "later (<em>delayed reward</em>). Maximising \\(R_{t+1}\\) is no longer enough: what has " +
    "to be maximised is the <strong>return</strong> \\(G_t\\). This is where Unit 2 begins.",

