  "t4.glosario.f4":
    "<td>\\(G_t\\)</td><td>return from \\(t\\)</td><td>B3, B4, B6</td><td>—</td>",
  "t4.glosario.f5":
    "<td>\\(\\gamma\\)</td><td>discount</td><td>the whole unit</td>"
